import type { ReactNode } from "react";

/**
 * Dawghwa's mascot, from the artwork supplied by the project owner
 * (brand/mascot-source.png). Variants are crops and scales generated by
 * scripts/brand-assets.py; the character itself is never redrawn.
 *  - full: the whole figure (onboarding, empty states, milestones)
 *  - head: head + book (profile, reader end panel)
 *  - face: tight face crop for 20-40px slots (logo, nav, avatar)
 * Use sparingly: one mascot per screen at most.
 */
import full from "@/assets/mascot/default.webp";
import full320 from "@/assets/mascot/default-320.webp";
import head from "@/assets/mascot/head.webp";
import face from "@/assets/mascot/face.webp";

export type Pose = "welcome" | "empty" | "error" | "offline" | "reading" | "done";
export type MascotVariant = "full" | "head" | "face";

export const hasMascot = (_pose?: Pose) => true;

export function Mascot({ variant = "full", size = 120, className = "state-art", pose }: { variant?: MascotVariant; size?: number; className?: string; pose?: Pose }) {
  const src = variant === "face" ? face : variant === "head" ? head : size <= 200 ? full320 : full;
  const srcSet = variant === "full" ? `${full320} 320w, ${full} 640w` : undefined;
  return <img className={className} src={src} srcSet={srcSet} sizes={srcSet ? `${size}px` : undefined} width={size} height={size} alt="" decoding="async" draggable={false} data-pose={pose} />;
}

/** Mascot with a short speech bubble, for empty / milestone moments. */
export function MascotSays({ children, size = 112, pose, variant = "full" }: { children: ReactNode; size?: number; pose?: Pose; variant?: MascotVariant }) {
  return (
    <div className="mascot-says">
      <span className="mascot-burst" aria-hidden="true">
        <Mascot variant={variant} size={size} pose={pose} className="mascot-img" />
      </span>
      <p className="bubble">{children}</p>
    </div>
  );
}
